input.oldString:
it('color include keeps only commanders whose identity is a subset of the included colors', () => {
  const monoBlack = makeSuggestion({ colorIdentity: ['B'], unitId: 'Black Mono' });
  const monoGreen = makeSuggestion({ colorIdentity: ['G'], unitId: 'Green Mono' });
  const golgari = makeSuggestion({ colorIdentity: ['B', 'G'], unitId: 'Golgari' });
  const abzan = makeSuggestion({ colorIdentity: ['W', 'B', 'G'], unitId: 'Abzan' });
  const wb = makeSuggestion({ colorIdentity: ['W', 'B'], unitId: 'WB' });
  const boros = makeSuggestion({ colorIdentity: ['W', 'R'], unitId: 'Boros' });

  const filters = { ...EMPTY_FILTERS, colors: { include: ['B'], exclude: [] } };
  const kept = applyFilters([monoBlack, monoGreen, golgari, abzan, wb, boros], filters);
  assert.strictEqual(kept.length, 3);
  const keptIds = new Set(kept.map((s) => s.colorIdentity));
  assert(keptIds.has(['B']));
  assert(keptIds.has(['G']));
  assert(keptIds.has(['B', 'G']));
});

it('color include keeps colourless commanders — empty identity is a subset of any set', () => {
  const monoBlack = makeSuggestion({ colorIdentity: ['B'], unitId: 'Black Mono' });
  const colorless = makeSuggestion({ colorIdentity: [], unitId: 'Colorless' });

  const filters = { ...EMPTY_FILTERS, colors: { include: ['B'], exclude: [] } };
  const kept = applyFilters([monoBlack, colorless], filters);
  assert.strictEqual(kept.length, 2);
});

